<template>
  <div>
    <div class="page-heading"><div><p class="eyebrow">EQUIPMENT · BOM · MTBF · NET REQUIREMENT</p><h1>设备与MRO闭环</h1><p>设备台账连接备件BOM、维护计划、故障可靠性、库存与采购申请。</p></div><el-button type="primary" @click="openEquipment()">新增设备</el-button></div>
    <div class="process-strip"><span>设备台账</span><i>→</i><span>设备BOM</span><i>→</i><span>维护与故障</span><i>→</i><span>MTBF</span><i>→</i><span>净需求</span><i>→</i><span>采购申请</span></div>
    <div class="table-toolbar"><el-input v-model.trim="keyword" clearable placeholder="搜索设备编码、名称或型号" @keyup.enter.native="search" @clear="search"/><el-select v-model="status" clearable placeholder="全部状态" @change="search"><el-option v-for="item in equipmentStatuses" :key="item.value" :label="item.label" :value="item.value"/></el-select><el-button icon="el-icon-search" @click="search">查询</el-button><el-button @click="keyword='';status='';search()">重置</el-button></div>
    <el-table v-loading="loading" :data="items" class="data-table" empty-text="暂无设备台账"><el-table-column prop="code" label="设备编码" width="145"/><el-table-column prop="name" label="设备名称" min-width="170"/><el-table-column prop="model" label="型号" width="135"/><el-table-column prop="factory_code" label="工厂" width="120"/><el-table-column prop="location" label="位置" min-width="140"/><el-table-column label="关键性" width="90"><template slot-scope="s"><el-tag :type="criticalType(s.row.criticality)">{{ criticalName(s.row.criticality) }}</el-tag></template></el-table-column><el-table-column label="状态" width="95"><template slot-scope="s">{{ equipmentStatusName(s.row.status) }}</template></el-table-column><el-table-column prop="responsible_person" label="负责人" width="105"/><el-table-column label="操作" width="210" fixed="right"><template slot-scope="s"><el-button type="text" @click="openDetail(s.row)">MRO闭环</el-button><el-button type="text" @click="openEquipment(s.row)">编辑</el-button><el-button type="text" class="danger-link" @click="removeEquipment(s.row)">删除</el-button></template></el-table-column></el-table>
    <div class="pagination-row"><span>共 {{ pagination.total }} 条</span><el-pagination background layout="sizes, prev, pager, next" :page-sizes="[10,20,50]" :current-page="pagination.page" :page-size="pagination.page_size" :total="pagination.total" @current-change="p=>{pagination.page=p;load()}" @size-change="n=>{pagination.page_size=n;search()}"/></div>

    <el-dialog :title="equipmentForm.id?'编辑设备':'新增设备'" :visible.sync="equipmentVisible" width="720px" :close-on-click-modal="false"><el-form ref="equipmentForm" :model="equipmentForm" :rules="equipmentRules" label-width="90px"><el-row :gutter="14"><el-col :span="12"><el-form-item label="设备编码" prop="code"><el-input v-model.trim="equipmentForm.code"/></el-form-item></el-col><el-col :span="12"><el-form-item label="设备名称" prop="name"><el-input v-model.trim="equipmentForm.name"/></el-form-item></el-col></el-row><el-row :gutter="14"><el-col :span="12"><el-form-item label="工厂" prop="factory_code"><el-select v-model="equipmentForm.factory_code" filterable style="width:100%"><el-option v-for="f in factories" :key="f.code" :label="`${f.code} ${f.name}`" :value="f.code"/></el-select></el-form-item></el-col><el-col :span="12"><el-form-item label="安装位置"><el-input v-model.trim="equipmentForm.location"/></el-form-item></el-col></el-row><el-row :gutter="14"><el-col :span="12"><el-form-item label="型号"><el-input v-model.trim="equipmentForm.model"/></el-form-item></el-col><el-col :span="12"><el-form-item label="制造商"><el-input v-model.trim="equipmentForm.manufacturer"/></el-form-item></el-col></el-row><el-row :gutter="14"><el-col :span="12"><el-form-item label="序列号"><el-input v-model.trim="equipmentForm.serial_no"/></el-form-item></el-col><el-col :span="12"><el-form-item label="投产日期"><el-date-picker v-model="equipmentForm.commissioned_date" value-format="yyyy-MM-dd" style="width:100%"/></el-form-item></el-col></el-row><el-row :gutter="14"><el-col :span="8"><el-form-item label="关键性"><el-select v-model="equipmentForm.criticality"><el-option label="关键" value="high"/><el-option label="重要" value="medium"/><el-option label="一般" value="low"/></el-select></el-form-item></el-col><el-col :span="8"><el-form-item label="状态"><el-select v-model="equipmentForm.status"><el-option v-for="item in equipmentStatuses" :key="item.value" :label="item.label" :value="item.value"/></el-select></el-form-item></el-col><el-col :span="8"><el-form-item label="负责人"><el-input v-model.trim="equipmentForm.responsible_person"/></el-form-item></el-col></el-row></el-form><span slot="footer"><el-button @click="equipmentVisible=false">取消</el-button><el-button type="primary" :loading="saving" @click="saveEquipment">保存设备</el-button></span></el-dialog>

    <el-dialog v-if="selected" :title="`${selected.code} · ${selected.name} MRO闭环`" :visible.sync="detailVisible" width="1220px" top="3vh" :close-on-click-modal="false"><el-tabs v-model="detailTab" @tab-click="loadDetail"><el-tab-pane label="设备BOM" name="bom"/><el-tab-pane label="维护计划" name="plans"/><el-tab-pane label="故障与MTBF" name="faults"/><el-tab-pane label="净需求与采购" name="requirements"/></el-tabs>
      <div v-if="detailTab==='bom'"><div class="section-action"><p>明确每台设备的备件用量、更换周期、安全数量与关键件属性。</p><el-button type="primary" size="small" @click="openBom()">添加BOM物料</el-button></div><el-table :data="bom.items" size="small"><el-table-column prop="material_code" label="物料编码" width="135"/><el-table-column prop="material_name" label="物料名称" min-width="160"/><el-table-column prop="quantity" label="装机数量" width="95"/><el-table-column prop="replacement_cycle_days" label="更换周期(天)" width="115"/><el-table-column prop="safety_quantity" label="安全数量" width="95"/><el-table-column label="关键备件" width="90"><template slot-scope="s">{{s.row.critical?'是':'否'}}</template></el-table-column><el-table-column prop="remark" label="说明" min-width="160"/><el-table-column label="操作" width="130"><template slot-scope="s"><el-button type="text" @click="openBom(s.row)">编辑</el-button><el-button type="text" class="danger-link" @click="removeChild('equipment-bom',s.row)">删除</el-button></template></el-table-column></el-table></div>
      <div v-else-if="detailTab==='plans'"><div class="section-action"><p>计划到期且关联物料的数量进入规划期净需求。</p><el-button type="primary" size="small" @click="openPlan()">新增维护计划</el-button></div><el-table :data="plans.items" size="small"><el-table-column prop="name" label="计划名称" min-width="170"/><el-table-column label="类型" width="100"><template slot-scope="s">{{planTypeName(s.row.plan_type)}}</template></el-table-column><el-table-column prop="interval_days" label="周期(天)" width="90"/><el-table-column prop="next_due_date" label="下次执行" width="110"/><el-table-column prop="material_code" label="备件编码" width="135"/><el-table-column prop="planned_quantity" label="计划用量" width="90"/><el-table-column prop="owner" label="负责人" width="100"/><el-table-column label="状态" width="80"><template slot-scope="s">{{planStatusName(s.row.status)}}</template></el-table-column><el-table-column label="操作" width="130"><template slot-scope="s"><el-button type="text" @click="openPlan(s.row)">编辑</el-button><el-button type="text" class="danger-link" @click="removeChild('maintenance-plans',s.row)">删除</el-button></template></el-table-column></el-table></div>
      <div v-else-if="detailTab==='faults'"><div class="metric-row"><div><span>已关闭故障</span><strong>{{reliability.failure_count||0}}</strong></div><div><span>MTBF</span><strong>{{reliability.mtbf_hours?reliability.mtbf_hours.toLocaleString()+' h':'数据不足'}}</strong></div><div class="method"><span>计算口径</span><p>{{reliability.method}}</p></div><el-button type="primary" size="small" @click="openFault()">登记故障</el-button></div><analysis-chart v-if="reliability.intervals&&reliability.intervals.length" :option="mtbfChart" class="small-chart"/><el-table :data="faults.items" size="small"><el-table-column prop="fault_no" label="故障编号" width="120"/><el-table-column prop="occurred_at" label="发生时间" width="165"><template slot-scope="s">{{time(s.row.occurred_at)}}</template></el-table-column><el-table-column prop="fault_category" label="故障类别" width="110"/><el-table-column prop="downtime_hours" label="停机小时" width="90"/><el-table-column prop="material_code" label="更换物料" width="130"/><el-table-column prop="quantity_used" label="耗用" width="70"/><el-table-column prop="cause" label="原因" min-width="150" show-overflow-tooltip/><el-table-column label="状态" width="80"><template slot-scope="s">{{s.row.status==='closed'?'已关闭':'处理中'}}</template></el-table-column><el-table-column label="操作" width="130"><template slot-scope="s"><el-button type="text" @click="openFault(s.row)">编辑</el-button><el-button type="text" class="danger-link" @click="removeChild('equipment-faults',s.row)">删除</el-button></template></el-table-column></el-table></div>
      <div v-else><div class="requirement-controls"><el-input-number v-model="horizon" :min="1" :max="730"/><span>规划天数</span><el-date-picker v-model="neededDate" value-format="yyyy-MM-dd" placeholder="采购需要日期"/><el-button type="primary" :loading="analyzing" @click="analyze">重新测算</el-button><el-button type="success" :disabled="!selectedRequirements.length" :loading="saving" @click="createRequisition">生成采购申请</el-button></div><el-alert v-if="analysis" :title="analysis.formula" :description="analysis.warnings.join('；')" :type="analysis.warnings.length?'warning':'success'" :closable="false" show-icon/><analysis-chart v-if="analysis&&analysis.items.length" :option="requirementChart" class="requirement-chart"/><el-table v-if="analysis" ref="requirementTable" :data="analysis.items" size="small" @selection-change="selectedRequirements=$event"><el-table-column type="selection" width="45" :selectable="row=>row.net_requirement>0"/><el-table-column prop="material_code" label="物料编码" width="130"/><el-table-column prop="material_name" label="物料" min-width="130"/><el-table-column prop="planned_demand" label="计划需求" width="90"/><el-table-column prop="corrective_demand" label="故障需求" width="90"/><el-table-column prop="safety_quantity" label="安全数量" width="90"/><el-table-column prop="available_stock" label="可用库存" width="90"/><el-table-column prop="in_transit" label="确认在途" width="90"/><el-table-column prop="net_requirement" label="净需求" width="90"><template slot-scope="s"><strong class="net">{{s.row.net_requirement}}</strong></template></el-table-column><el-table-column label="计算证据" min-width="190"><template slot-scope="s">周期{{s.row.evidence.replacement_cycle_days}}天 · 故障{{s.row.evidence.closed_faults}}次 · MTBF {{s.row.evidence.mtbf_hours||'-'}}h</template></el-table-column></el-table></div>
    </el-dialog>

    <el-dialog :title="bomForm.id?'编辑BOM物料':'添加BOM物料'" :visible.sync="bomVisible" width="600px" append-to-body><el-form label-width="105px"><el-form-item label="物料"><el-select v-model="bomForm.material_id" filterable :disabled="!!bomForm.id" style="width:100%"><el-option v-for="m in materials" :key="m.id" :label="`${m.code} ${m.name}`" :value="m.id"/></el-select></el-form-item><el-row><el-col :span="8"><el-form-item label="装机数量"><el-input-number v-model="bomForm.quantity" :min="0.01"/></el-form-item></el-col><el-col :span="8"><el-form-item label="更换周期"><el-input-number v-model="bomForm.replacement_cycle_days" :min="1"/></el-form-item></el-col><el-col :span="8"><el-form-item label="安全数量"><el-input-number v-model="bomForm.safety_quantity" :min="0"/></el-form-item></el-col></el-row><el-form-item label="关键备件"><el-switch v-model="bomForm.critical"/></el-form-item><el-form-item label="说明"><el-input v-model.trim="bomForm.remark"/></el-form-item></el-form><span slot="footer"><el-button @click="bomVisible=false">取消</el-button><el-button type="primary" :loading="saving" @click="saveBom">保存</el-button></span></el-dialog>
    <el-dialog :title="planForm.id?'编辑维护计划':'新增维护计划'" :visible.sync="planVisible" width="650px" append-to-body><el-form label-width="100px"><el-form-item label="计划名称"><el-input v-model.trim="planForm.name"/></el-form-item><el-row><el-col :span="12"><el-form-item label="计划类型"><el-select v-model="planForm.plan_type"><el-option label="预防性维护" value="preventive"/><el-option label="预测性维护" value="predictive"/><el-option label="点检" value="inspection"/></el-select></el-form-item></el-col><el-col :span="12"><el-form-item label="周期天数"><el-input-number v-model="planForm.interval_days" :min="1"/></el-form-item></el-col></el-row><el-row><el-col :span="12"><el-form-item label="下次执行"><el-date-picker v-model="planForm.next_due_date" value-format="yyyy-MM-dd"/></el-form-item></el-col><el-col :span="12"><el-form-item label="负责人"><el-input v-model.trim="planForm.owner"/></el-form-item></el-col></el-row><el-row><el-col :span="16"><el-form-item label="计划备件"><el-select v-model="planForm.material_code" clearable filterable><el-option v-for="m in materials" :key="m.code" :label="`${m.code} ${m.name}`" :value="m.code"/></el-select></el-form-item></el-col><el-col :span="8"><el-form-item label="计划用量"><el-input-number v-model="planForm.planned_quantity" :min="0"/></el-form-item></el-col></el-row><el-form-item label="状态"><el-select v-model="planForm.status"><el-option label="启用" value="active"/><el-option label="暂停" value="paused"/><el-option label="已完成" value="completed"/></el-select></el-form-item></el-form><span slot="footer"><el-button @click="planVisible=false">取消</el-button><el-button type="primary" :loading="saving" @click="savePlan">保存</el-button></span></el-dialog>
    <el-dialog :title="faultForm.id?'更新故障':'登记故障'" :visible.sync="faultVisible" width="720px" append-to-body><el-form label-width="100px"><el-row><el-col :span="12"><el-form-item label="发生时间"><el-date-picker v-model="faultForm.occurred_at" type="datetime" value-format="yyyy-MM-ddTHH:mm:ss"/></el-form-item></el-col><el-col :span="12"><el-form-item label="恢复时间"><el-date-picker v-model="faultForm.restored_at" type="datetime" value-format="yyyy-MM-ddTHH:mm:ss"/></el-form-item></el-col></el-row><el-row><el-col :span="12"><el-form-item label="故障类别"><el-input v-model.trim="faultForm.fault_category"/></el-form-item></el-col><el-col :span="12"><el-form-item label="状态"><el-radio-group v-model="faultForm.status"><el-radio label="open">处理中</el-radio><el-radio label="closed">已关闭</el-radio></el-radio-group></el-form-item></el-col></el-row><el-form-item label="故障原因"><el-input v-model.trim="faultForm.cause" type="textarea" :rows="2"/></el-form-item><el-form-item label="处置措施"><el-input v-model.trim="faultForm.action" type="textarea" :rows="2"/></el-form-item><el-row><el-col :span="16"><el-form-item label="更换物料"><el-select v-model="faultForm.material_code" clearable filterable><el-option v-for="m in materials" :key="m.code" :label="`${m.code} ${m.name}`" :value="m.code"/></el-select></el-form-item></el-col><el-col :span="8"><el-form-item label="耗用数量"><el-input-number v-model="faultForm.quantity_used" :min="0"/></el-form-item></el-col></el-row><el-form-item label="报告人"><el-input v-model.trim="faultForm.reported_by"/></el-form-item></el-form><span slot="footer"><el-button @click="faultVisible=false">取消</el-button><el-button type="primary" :loading="saving" @click="saveFault">保存</el-button></span></el-dialog>
  </div>
</template>

<script>
import AnalysisChart from "../components/AnalysisChart.vue";
import { api, fetchMasterData } from "../api/client";
const equipmentBlank=()=>({id:"",code:"",name:"",factory_code:"",location:"",model:"",manufacturer:"",serial_no:"",commissioned_date:null,criticality:"medium",status:"running",responsible_person:""});
const bomBlank=()=>({id:"",material_id:"",quantity:1,replacement_cycle_days:365,safety_quantity:0,critical:false,remark:""});
const planBlank=()=>({id:"",name:"",plan_type:"preventive",interval_days:90,next_due_date:"",material_code:"",planned_quantity:1,status:"active",owner:""});
const faultBlank=()=>({id:"",occurred_at:"",restored_at:null,fault_category:"",cause:"",action:"",material_code:"",quantity_used:0,status:"open",reported_by:""});
export default {components:{AnalysisChart},data:()=>({items:[],factories:[],materials:[],keyword:"",status:"",loading:false,saving:false,analyzing:false,equipmentVisible:false,detailVisible:false,bomVisible:false,planVisible:false,faultVisible:false,equipmentForm:equipmentBlank(),bomForm:bomBlank(),planForm:planBlank(),faultForm:faultBlank(),selected:null,detailTab:"bom",bom:{items:[]},plans:{items:[]},faults:{items:[]},reliability:{},analysis:null,horizon:90,neededDate:"",selectedRequirements:[],pagination:{page:1,page_size:10,total:0},equipmentStatuses:[{value:"running",label:"运行"},{value:"maintenance",label:"检修"},{value:"stopped",label:"停机"},{value:"retired",label:"退役"}],equipmentRules:{code:[{required:true,message:"请输入设备编码",trigger:"blur"}],name:[{required:true,message:"请输入设备名称",trigger:"blur"}],factory_code:[{required:true,message:"请选择工厂",trigger:"change"}]}}),computed:{mtbfChart(){return {title:{text:"相邻故障间隔（MTBF样本）"},tooltip:{trigger:"axis"},xAxis:{type:"category",data:this.reliability.intervals.map(x=>`${x.from}→${x.to}`)},yAxis:{type:"value",name:"小时"},series:[{type:"bar",data:this.reliability.intervals.map(x=>x.hours)}]};},requirementChart(){return {title:{text:"MRO需求、库存与净需求"},tooltip:{trigger:"axis"},legend:{top:28},grid:{top:65,left:55,right:20,bottom:55},xAxis:{type:"category",data:this.analysis.items.map(x=>x.material_code),axisLabel:{rotate:25}},yAxis:{type:"value",name:"数量"},series:[{name:"总需求",type:"bar",data:this.analysis.items.map(x=>x.gross_demand)},{name:"可用+在途",type:"bar",data:this.analysis.items.map(x=>x.available_stock+x.in_transit)},{name:"净需求",type:"line",data:this.analysis.items.map(x=>x.net_requirement)}]};}},async created(){const [factories,materials]=await Promise.all([fetchMasterData("factories",{page:1,page_size:100,unfiltered:true}),fetchMasterData("materials",{page:1,page_size:100,unfiltered:true})]);this.factories=factories.items;this.materials=materials.items;await this.load();},methods:{error(e){this.$message.error(e.response?.data?.detail||"操作失败");},criticalName(v){return {high:"关键",medium:"重要",low:"一般"}[v]||v;},criticalType(v){return {high:"danger",medium:"warning",low:"info"}[v];},equipmentStatusName(v){return this.equipmentStatuses.find(x=>x.value===v)?.label||v;},planTypeName(v){return {preventive:"预防维护",predictive:"预测维护",inspection:"点检"}[v]||v;},planStatusName(v){return {active:"启用",paused:"暂停",completed:"完成"}[v]||v;},time(v){return v?new Date(v).toLocaleString("zh-CN",{hour12:false}):"-";},async load(){this.loading=true;try{const r=(await api.get("/equipment",{params:{...this.pagination,keyword:this.keyword,status:this.status}})).data;this.items=r.items;this.pagination.total=r.total;}catch(e){this.error(e);}finally{this.loading=false;}},search(){this.pagination.page=1;this.load();},openEquipment(row){this.equipmentForm=row?{...row}:equipmentBlank();this.equipmentVisible=true;},saveEquipment(){this.$refs.equipmentForm.validate(async valid=>{if(!valid)return;this.saving=true;try{await (this.equipmentForm.id?api.patch(`/equipment/${this.equipmentForm.id}`,this.equipmentForm):api.post("/equipment",this.equipmentForm));this.equipmentVisible=false;await this.load();this.$message.success("设备台账已保存");}catch(e){this.error(e);}finally{this.saving=false;}});},async removeEquipment(row){try{await this.$confirm(`删除设备 ${row.code}？`,"删除确认",{type:"warning"});await api.delete(`/equipment/${row.id}`);await this.load();}catch(e){if(e!=="cancel")this.error(e);}},async openDetail(row){this.selected=row;this.detailTab="bom";this.detailVisible=true;await this.loadDetail();},async loadDetail(){if(!this.selected)return;try{const id=this.selected.id;if(this.detailTab==="bom")this.bom=(await api.get(`/equipment/${id}/bom`,{params:{page:1,page_size:100}})).data;else if(this.detailTab==="plans")this.plans=(await api.get(`/equipment/${id}/maintenance-plans`,{params:{page:1,page_size:100}})).data;else if(this.detailTab==="faults"){[this.faults,this.reliability]=await Promise.all([api.get(`/equipment/${id}/faults`,{params:{page:1,page_size:100}}).then(r=>r.data),api.get(`/equipment/${id}/reliability`).then(r=>r.data)]);}else if(!this.analysis)await this.analyze();}catch(e){this.error(e);}},openBom(row){this.bomForm=row?{...row}:bomBlank();this.bomVisible=true;},async saveBom(){if(!this.bomForm.material_id)return this.$message.warning("请选择物料");this.saving=true;try{await (this.bomForm.id?api.patch(`/equipment-bom/${this.bomForm.id}`,this.bomForm):api.post(`/equipment/${this.selected.id}/bom`,this.bomForm));this.bomVisible=false;await this.loadDetail();}catch(e){this.error(e);}finally{this.saving=false;}},openPlan(row){this.planForm=row?{...row}:planBlank();this.planVisible=true;},async savePlan(){if(!this.planForm.name||!this.planForm.next_due_date)return this.$message.warning("请填写计划名称和下次执行日期");this.saving=true;try{await (this.planForm.id?api.patch(`/maintenance-plans/${this.planForm.id}`,this.planForm):api.post(`/equipment/${this.selected.id}/maintenance-plans`,this.planForm));this.planVisible=false;await this.loadDetail();}catch(e){this.error(e);}finally{this.saving=false;}},openFault(row){this.faultForm=row?{...row,occurred_at:(row.occurred_at||"").slice(0,19),restored_at:row.restored_at?(row.restored_at).slice(0,19):null}:faultBlank();this.faultVisible=true;},async saveFault(){if(!this.faultForm.occurred_at)return this.$message.warning("请选择故障发生时间");if(this.faultForm.status==="closed"&&!this.faultForm.restored_at)return this.$message.warning("关闭故障必须填写恢复时间");this.saving=true;try{await (this.faultForm.id?api.patch(`/equipment-faults/${this.faultForm.id}`,this.faultForm):api.post(`/equipment/${this.selected.id}/faults`,this.faultForm));this.faultVisible=false;await this.loadDetail();}catch(e){this.error(e);}finally{this.saving=false;}},async removeChild(path,row){try{await this.$confirm("删除该记录？","删除确认",{type:"warning"});await api.delete(`/${path}/${row.id}`);await this.loadDetail();}catch(e){if(e!=="cancel")this.error(e);}},async analyze(){this.analyzing=true;try{this.analysis=(await api.post("/mro-net-requirements/analyze",{equipment_id:this.selected.id,horizon_days:this.horizon,needed_date:this.neededDate||null})).data;this.selectedRequirements=[];this.$nextTick(()=>this.analysis.items.filter(x=>x.net_requirement>0).forEach(x=>this.$refs.requirementTable?.toggleRowSelection(x,true)));}catch(e){this.error(e);}finally{this.analyzing=false;}},async createRequisition(){this.saving=true;try{const r=(await api.post("/mro-net-requirements/create-requisition",{equipment_id:this.selected.id,horizon_days:this.horizon,needed_date:this.neededDate||null,selected_material_codes:this.selectedRequirements.map(x=>x.material_code)})).data;this.$message.success(`已生成采购申请 ${r.requisition.request_no}`);}catch(e){this.error(e);}finally{this.saving=false;}}}};
</script>
